def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d = d + 1
    return True

def claim(kind, n):
    if kind == "A":
        return (n * n + n) % 2 == 0
    if kind == "B":
        return n % 2 == 0 or is_prime(n)
    if kind == "C":
        return is_prime(2 ** n - 1)
    return n * n > 10

def hunt(case, name, kind, values):
    print(f"Case {case}: {name}")
    first = "none"
    for n in values:
        if not claim(kind, n) and first == "none":
            first = n
    print(f"  holds for all: {all(claim(kind, n) for n in values)}, first counterexample: {first}")

hunt("1 · a true claim", "n*n + n is even", "A", range(1, 21))
hunt("2 · a quick failure", "if n is odd, then n is prime", "B", range(1, 21))
hunt("3 · a failure far out", "2**n - 1 is prime for prime n", "C", [2, 3, 5, 7, 11, 13])
hunt("4 · the negation", "every n has n*n > 10", "D", range(1, 21))

