        if not 2 ** n >= n * n and first_b == "none":
            first_b = n
        if not n * n < 100 and first_c == "none":
            first_c = n
    print(f"N = {N}: A {first_a == 'none'} ({first_a}), B {first_b == 'none'} ({first_b}), C {first_c == 'none'} ({first_c})")
